{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the goal to maximize total profit (unit price minus raw material cost minus processing cost), or to maximize total revenue (unit price only), or to minimize total cost?"
  ],
  "rationale": "The response asks for a single policy choice among three mutually exclusive objective functions, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits (maximum number of units that can be sold) for each product, or can the factory produce and sell unlimited quantities of each product?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand limits exist or if quantities are unlimited. Although it presents two options, it requires a single policy decision/answer."
}

