  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product, must the number of units that complete stage A equal the number that complete stage B (i.e., every unit that enters stage A must also go through stage B, with no work-in-progress or leftover units allowed)?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy constraint regarding flow balance between stages A and B."
}

