  "atomic_questions": [
    "The processing cost per machine hour (e.g., 0.05 yuan/hour for A1) — is this a variable cost that applies only to the machine hours actually used, or is it a fixed cost charged for the full available hours regardless of usage?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the processing cost (variable vs. fixed), which constitutes one independent semantic query."
}

